# Return the contents of a named configuration block.
def block(lines, tag, start=0, end=None):
    if end is None:
        end = len(lines)
    a = next(i for i in range(start, end) if lines[i].strip() == '[' + tag + ']')
    b = next(i for i in range(a + 1, end) if lines[i].strip() == '[/' + tag + ']')
    return a, b

# Compare numbers with the plan tolerance and other words exactly.
def equal(actual, expected):
    if len(actual) != len(expected):
        return False
    for a, b in zip(actual, expected):
        if a == b:
            continue
        try:
            if abs(float(a) - float(b)) <= 1e-9:
                continue
        except ValueError:
            pass
        return False
    return True

cache = {}
errors = []
for file, section, entity, key, expected in ROWS:
    if file not in cache:
        cache[file] = (ROOT / file).read_text(encoding='utf-8').splitlines()
    lines = cache[file]
    try:
        if file == 'config/creatureSkills.cfg':
            kind = 'AURA_ALLY' if entity == 'AuraAlly' else 'SKELARMY'
            hits = []
            for tag in ('Skill', 'TierFour'):
                for m in re.finditer(r'^\[' + tag + r'\]\s*$(.*?)^\[/' + tag + r'\]', '\n'.join(lines), re.M | re.S):
                    part = m.group(1).splitlines()
                    if any(line.split()[:1] == ['Kind'] and line.split()[1].startswith(kind) for line in part):
                        hits += [line.split()[1:] for line in part if line.split()[:1] == [key]]
            ok = bool(hits) and all(equal(hit, expected.split()) for hit in hits)
        elif file == 'config/creatures.cfg':
            candidates = [i for i, line in enumerate(lines) if line.strip() == '[Creature]']
            c = next(i for i in candidates if lines[i+1].split()[:2] == ['Name', entity])
            ce = next(i for i in range(c, len(lines)) if lines[i].strip() == '[/Creature]')
            tag = {'Stats':'Stats', 'Creature/Stats':'Stats', 'MoodModifiers':'MoodModifiers', 'RoomAffinity':'RoomAffinity', 'Creature/CreatureSkills':'CreatureSkills'}[section]
            a, b = block(lines, tag, c, ce)
            if section == 'Creature/CreatureSkills':
                hits = [line.split() for line in lines[a:b] if line.split()[:1] == ['Melee']]
                assert len(hits) == 1, (entity, key)
                row = hits[0]
                ok = equal([row[10 if 'PhyMin' in key else 11]], expected.split())
            else:
                hits = [line.split()[1:] for line in lines[a:b] if line.split()[:1] == [key]]
                ok = not hits if expected == '(remove)' else len(hits) == 1 and equal(hits[0], expected.split())
        elif file == 'config/items.cfg':
            item, quality = entity.split('/')
            effect = key.split()[1]
            start = next(i for i, line in enumerate(lines) if line.split()[:2] == ['Id', item])
            start = next(i for i in range(start, len(lines)) if lines[i].split()[:2] == ['Name', quality])
            hit = next(line.split()[2:] for line in lines[start:] if line.split()[:2] == ['Effect', effect])
            ok = equal(hit, expected.split())
        elif file == 'config/spawnconditions.cfg':
            target = key.split()[1]
            start = next(i for i, line in enumerate(lines) if line.split()[:2] == ['CreatureClass', entity])
            hit = next(line.split()[2:] for line in lines[start:] if line.split()[:2] == ['Creature', target])
            ok = equal(hit, expected.split())
        elif section == 'ResearchEffects':
            hits = [line.split()[2:] for line in lines if line.split()[:2] == [entity, key]]
            ok = not hits if expected == '(remove)' else len(hits) == 1 and equal(hits[0], expected.split())
        else:
            a, b = block(lines, 'EquipmentDefinitions' if file == 'config/equipments.cfg' else section)
            hits = [line.split()[1:] for line in lines[a:b] if line.split()[:1] == [key]]
            ok = not hits if expected == '(remove)' else len(hits) == 1 and equal(hits[0], expected.split())
        if not ok:
            errors.append((file, section, entity, key, expected))
    except (StopIteration, IndexError, KeyError, ValueError) as exc:
        errors.append((file, section, entity, key, expected, str(exc)))
if errors:
    for error in errors:
        print('FAIL:', error)
    raise SystemExit(1)
print('rebalance config ok:', len(ROWS), 'rows')
